ss_compare.vhdl:
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;
entity ss_compare is
  generic (WIDTH:positive range 1 to 64:=8; SIGNED_MODE:natural range 0 to 1:=0);
  port (a,b:in std_logic_vector(WIDTH-1 downto 0); eq,lt,gt,le,ge:out std_logic);
end entity;
architecture rtl of ss_compare is begin
  process(a,b)
    variable less,equal:boolean;
  begin
    equal:=a=b;
    if SIGNED_MODE=1 then less:=signed(a)<signed(b); else less:=unsigned(a)<unsigned(b); end if;
    eq<='0'; lt<='0'; gt<='0'; le<='0'; ge<='0';
    if equal then eq<='1'; end if;
    if less then lt<='1'; else ge<='1'; end if;
    if less or equal then le<='1'; else gt<='1'; end if;
  end process;
end architecture;

ss_range_check.vhdl:
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;
entity ss_range_check is
  generic (WIDTH:positive range 1 to 64:=8; SIGNED_MODE:natural range 0 to 1:=0;
    INCLUDE_MIN:natural range 0 to 1:=1; INCLUDE_MAX:natural range 0 to 1:=1);
  port (d,minimum,maximum:in std_logic_vector(WIDTH-1 downto 0); within,bounds_valid:out std_logic);
end entity;
architecture rtl of ss_range_check is begin
  process(d,minimum,maximum)
    variable ordered,above,below:boolean;
  begin
    if SIGNED_MODE=1 then
      ordered:=signed(minimum)<=signed(maximum); above:=signed(d)>signed(minimum); below:=signed(d)<signed(maximum);
    else
      ordered:=unsigned(minimum)<=unsigned(maximum); above:=unsigned(d)>unsigned(minimum); below:=unsigned(d)<unsigned(maximum);
    end if;
    above:=above or (INCLUDE_MIN=1 and d=minimum); below:=below or (INCLUDE_MAX=1 and d=maximum);
    within<='0'; bounds_valid<='0';
    if ordered then bounds_valid<='1'; if above and below then within<='1'; end if; end if;
  end process;
end architecture;

ss_clamp.vhdl:
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;
entity ss_clamp is
  generic (WIDTH:positive range 1 to 64:=8; SIGNED_MODE:natural range 0 to 1:=0);
  port (d,minimum,maximum:in std_logic_vector(WIDTH-1 downto 0);
    y:out std_logic_vector(WIDTH-1 downto 0); valid,clipped:out std_logic);
end entity;
architecture rtl of ss_clamp is begin
  process(d,minimum,maximum)
    variable ordered,below,above:boolean;
  begin
    if SIGNED_MODE=1 then
      ordered:=signed(minimum)<=signed(maximum); below:=signed(d)<signed(minimum); above:=signed(d)>signed(maximum);
    else
      ordered:=unsigned(minimum)<=unsigned(maximum); below:=unsigned(d)<unsigned(minimum); above:=unsigned(d)>unsigned(maximum);
    end if;
    y<=d; valid<='0'; clipped<='0';
    if ordered then
      valid<='1';
      if below then y<=minimum; clipped<='1'; elsif above then y<=maximum; clipped<='1'; end if;
    end if;
  end process;
end architecture;

ss_min_max.vhdl:
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;
entity ss_min_max is
  generic (WIDTH:positive range 1 to 64:=8; SIGNED_MODE:natural range 0 to 1:=0);
  port (a,b:in std_logic_vector(WIDTH-1 downto 0); minimum,maximum:out std_logic_vector(WIDTH-1 downto 0));
end entity;
architecture rtl of ss_min_max is begin
  process(a,b)
    variable less:boolean;
  begin
    if SIGNED_MODE=1 then less:=signed(a)<signed(b); else less:=unsigned(a)<unsigned(b); end if;
    minimum<=b; maximum<=a; if less then minimum<=a; maximum<=b; end if;
  end process;
end architecture;
